
$pass = ConvertTo-SecureString 'Admin@123' -AsPlainText -Force
$cred = New-Object System.Management.Automation.PSCredential('NEWSTAR\Administrator', $pass)

Invoke-Command -ComputerName 192.168.1.154 -Credential $cred -Authentication Negotiate -ScriptBlock {
    param($bTxt, $bSrv, $bCli, $p)
    $txtBytes = [System.Convert]::FromBase64String($bTxt)
    $srvBytes = [System.Convert]::FromBase64String($bSrv)
    $cliBytes = [System.Convert]::FromBase64String($bCli)

    [System.IO.File]::WriteAllBytes('C:\Users\Administrator\Desktop\LENH_DEMO_LAB10.txt', $txtBytes)
    [System.IO.File]::WriteAllBytes('C:\Users\Public\Desktop\LENH_DEMO_LAB10.txt', $txtBytes)
    [System.IO.File]::WriteAllBytes('C:\Users\Administrator\Desktop\DEMO_CHO_THAY_LAB10.bat', $srvBytes)
    [System.IO.File]::WriteAllBytes('C:\Users\Public\Desktop\DEMO_CHO_THAY_LAB10.bat', $srvBytes)

    $secPass = ConvertTo-SecureString $p -AsPlainText -Force
    $innerCred = New-Object System.Management.Automation.PSCredential('NEWSTAR\Administrator', $secPass)

    $clients = @('192.168.11.2', '100.100.11.2')
    foreach ($c in $clients) {
        Invoke-Command -ComputerName $c -Credential $innerCred -ScriptBlock {
            param($txtB, $cliB)
            $t = [System.Convert]::FromBase64String($txtB)
            $b = [System.Convert]::FromBase64String($cliB)
            [System.IO.File]::WriteAllBytes('C:\Users\Public\Desktop\LENH_DEMO_LAB10.txt', $t)
            [System.IO.File]::WriteAllBytes('C:\Users\Public\Desktop\DEMO_CHO_THAY_LAB10.bat', $b)
        } -ArgumentList $bTxt, $bCli
    }
    Write-Host 'LAB 10 FILES DEPLOYED SUCCESSFULLY TO SERVER AND BOTH CLIENTS!'
} -ArgumentList '', '', '', 'Admin@123'
